[{"fieldname": "print_heading_template", "fieldtype": "Custom HTML", "options": "
"}, {"fieldtype": "Section Break", "label": ""}, {"fieldtype": "Column Break"}, {"fieldname": "_custom_html", "print_hide": 0, "label": "Custom HTML", "fieldtype": "HTML", "options": "<style>
    body {
        font-size: 12px;
        font-family: Arial, sans-serif;
    }
    .center { text-align: center; }
    .title { font-weight: bold; margin: 5px 0 10px; }

    .line {
        display: inline-block;
        border-bottom: 1px solid #000;
        min-width: 220px;
        height: 12px;
    }
    .small-line {
        display: inline-block;
        border-bottom: 1px solid #000;
        min-width: 120px;
        height: 12px;
    }

    table {
        width: 100%;
        border-collapse: collapse;
        margin-top: 5px;
    }
    table, th, td {
        border: 1px solid black;
    }
    th, td {
        padding: 3px;
        font-size: 12px;
    }
    .no-border td {
        border: none;
        padding: 2px;
    }

    /* Header info font size (same as Department line) */
    .header-info {
        font-size: 13px;
    }
</style>

<!-- HEADER -->
<div class="center">
    <h3>Virgin Plaza Returnable Gate Pass (NRGP)</h3>
</div>

<!-- GATE PASS INFO -->
<table class="no-border">
    <tr>
        <td class="header-info"><b>Gate Pass No:</b> {{ doc.name }}</td>
    </tr>
    <tr>
        <td class="header-info">
            <b>Date:</b>
                {{ doc.date }}
            
        </td>
    </tr>
    <tr>
        <td class="header-info">
            <b>Time:</b>
              {{ frappe.utils.format_time(doc.time, "hh:mm a") }}

        </td>
    </tr>
     <tr>
        <td class="header-info"><b>Gate Pass Validity Date and Time:</b> {{ doc.valid_till}}</td>
    </tr>
</table>

<!-- SECTION 1 -->
<div style="line-height: 2; margin-bottom: 5px;">
    <p style="margin: 2px 0;">
        <b>1. Resident/Tenant/Company Name:</b>
        {{ doc.residenttenantcompany_name or "" }}
    </p>

    <p style="margin: 2px 0;">
        <b>Office / Shop / Apartment No:</b>
        {{ doc.officeshopapartment_no or "" }}
    </p>

    <p style="margin: 2px 0;">
        <b>Department (if applicable):</b>
        {{ doc.department_if_applicable or "" }}
    </p>
</div>
<!-- SECTION 2: Material Description -->
<p><b>2. Material Description:</b></p>
<table>
    <tr>
        <th>S/N</th>
        <th>Item Name</th>
        <th>Item Descriptions</th>
        <th>Serial no. if any</th>
        <th>Quantity</th>
        <th>Remarks</th>
    </tr>
    {% if doc.items %}
        {% for row in doc.items %}
        <tr>
            <td>{{ loop.index }}</td>
            <td>{{ row.item_name }}</td>
            <td>{{ row.description }}</td>
            <td>{{ row.serial_no }}</td>
            <td>{{ row.quantity }}</td>
            <td>{{ row.remark }}</td>
        </tr>
        {% endfor %}
    {% endif %}
</table>
<br>
<!-- SECTION 3: Reason -->
<p><b>3. Reason for the Gate pass:</b></p>
<p>
Reason for the Gate pass please specify:
{% if doc.reason_for_the_gate_pass %}
    {{ doc.reason_for_the_gate_pass }}
{% else %}
    <span class="line"></span>
{% endif %}
</p>
<br>
<!-- SECTION 4: Authorization -->
<p style="line-height: 2; margin: 2px 0;">
    <b>3. Authorization by:</b>
    {{ doc.authorized_by_full_name }}
    <span style="float:right;">
        <b>Authorized On:</b> 
        {{ frappe.utils.formatdate(doc.authorized_on, "d/MM/YYYY") }} 
        {{ frappe.utils.format_time(doc.authorized_on, "hh:mm a") }}
    </span>
</p>

<!-- SECTION 5: Approved by -->
<p style="line-height: 2; margin: 2px 0;">
    <b>4. Approved by:</b>
    {{ doc.approved_by_full_name }}
    <span style="float:right;">
        <b>Approved On:</b>
        {{ frappe.utils.formatdate(doc.approved_on, "d/MM/YYYY") }} 
        {{ frappe.utils.format_time(doc.approved_on, "hh:mm a") }}
    </span>
</p>

<!-- SECTION 6: Security Use only -->
<p style="line-height: 2; margin: 2px 0;">
    <b>5. Security Use only:</b>
</p>

<p style="line-height: 2; margin: 2px 0;">
    Items physically verified by: <span>{{doc.item_physically_verified_by}}</span>
    Remarks: <span>{{doc.remark}}</span>
</p>

<p style="line-height: 2; margin: 2px 0;">
    Signature: <span>{{doc.signature}}</span>
    Date: <span>{{doc.verified_date}}</span>
</p>
<!-- FOOTER -->
<p style="font-size:10px;">
<b>Note:</b> {{ doc.note }}
</p>
"}]
